static double Traction(const tsymatrix3d& s,tdouble3 n){return s.xx*n.x*n.x+s.yy*n.y*n.y+s.zz*n.z*n.z+2.*(s.xy*n.x*n.y+s.yz*n.y*n.z+s.xz*n.x*n.z);}
static tsymatrix3d TotalStress(tsymatrix3d s,double p){s.xx-=p;s.yy-=p;s.zz-=p;return s;}
