// Independent radial certificates; no vector-RV form/contraction identity is used.
static double GammaCount(std::uint64_t n){const double t=double(n)*(.5*DBL_EPSILON);Need(Finite(t)&&t<1.,"Invalid radial arithmetic operation count");return t/(1.-t);}
static double OneNorm(tdouble3 x){return fabs(x.x)+fabs(x.y)+fabs(x.z);}
static double InfNorm(tdouble3 x){return (std::max)({fabs(x.x),fabs(x.y),fabs(x.z)});}
static double MatInf(Mat2 a){return (std::max)(fabs(a.xx)+fabs(a.xz),fabs(a.zx)+fabs(a.zz));}
static double ProductScale(Mat2 a,tdouble3 d){return (std::max)(fabs(a.xx*d.x)+fabs(a.xz*d.z),fabs(a.zx*d.x)+fabs(a.zz*d.z));}
static double Limiter(double s,double q){Need(Finite(s)&&Finite(q),"Nonfinite radial limiter input");if(!(s<0&&q<0))return 0.;return (std::min)(-s,-q);}
