 Need(s.dissipation_D>=0&&Finite(Q),"Negative radial dissipation/nonfinite Euler Q");s.power_error=fabs(s.node_power+s.dissipation_D);s.power_budget=s.power_gamma*(pairPowerScale+nodePowerScale)/(1.-s.power_gamma);s.net_norm=Len(net);s.net_budget=s.net_gamma*pairForceL1/(1.-GammaCount(4*E));s.torque_reduce_error=fabs(s.node_torque-s.pair_torque);s.central_budget/=1.-GammaCount(8*E);s.torque_reduce_budget=s.torque_gamma*(torqueMapScale+nodeTorqueScale+fabs(s.pair_torque))/(1.-s.torque_gamma);s.torque_budget=s.central_budget+s.torque_reduce_budget;
