 Need(s.power_error<=s.power_budget&&s.node_power<=s.power_budget&&s.net_norm<=s.net_budget&&fabs(s.pair_torque)<=s.central_budget&&s.torque_reduce_error<=s.torque_reduce_budget&&fabs(s.node_torque)<=s.torque_budget,"Independent central radial power/net/torque certificate failed");
